<div class="page-heading"><div><span class="kicker">ACCESS CONTROL</span><h1>User roles</h1><p>Only an existing Security Department user can elevate or reduce account privileges.</p></div><span class="panel-badge">SECURITY DEPARTMENT ONLY</span></div>
<section class="panel"><div class="panel-heading"><div><span class="kicker">DIRECTORY</span><h2><?= count($users) ?> registered users</h2></div></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Email</th><th>Current role</th><th>Created</th><th>Change access</th></tr></thead><tbody>
<?php foreach ($users as $account): ?><tr><td><div class="user-cell"><span class="avatar"><?= e(strtoupper(substr($account['name'], 0, 1))) ?></span><strong><?= e($account['name']) ?><?= (int) $account['id'] === (int) Auth::user()['id'] ? ' (you)' : '' ?></strong></div></td><td><?= e($account['email']) ?></td><td><span class="role-pill role-<?= e($account['role']) ?>"><?= $account['role'] === 'security_department' ? 'Security Department' : 'Analyst' ?></span></td><td><?= e(format_datetime($account['created_at'], 'd M Y')) ?></td><td><form method="post" action="<?= e(url('user-role')) ?>" class="role-form"><?= Csrf::field() ?><input type="hidden" name="user_id" value="<?= (int) $account['id'] ?>"><select name="role" aria-label="Role for <?= e($account['name']) ?>"><option value="analyst"<?= selected($account['role'], 'analyst') ?>>Analyst</option><option value="security_department"<?= selected($account['role'], 'security_department') ?>>Security Department</option></select><button class="button button-secondary button-small" type="submit">Save</button></form></td></tr><?php endforeach; ?>
